{"path":"etl/dedupe.py","content":""""Remove duplicate records, keeping the first occurrence.

Fast path: keys that hash successfully go into a set (O(1) lookups).
Fallback: unhashable keys (plain dicts are never hashable, and custom
``key`` functions may return dicts or lists) are compared with ``==``
against a small list, preserving the original duplicate semantics.
"""


def dedupe(records, key=None):
    if key is None:
        seen = set()
        unhashable = []
        out = []
        for r in records:
            try:
                h = hash(r)
            except TypeError:
                if r in unhashable:
                    continue
                unhashable.append(r)
                out.append(r)
            else:
                if h in seen:
                    continue
                seen.add(h)
                out.append(r)
    else:
        seen = set()
        unhashable = []
        out = []
        for r in records:
            k = key(r)
            try:
                h = hash(k)
            except TypeError:
                if k in unhashable:
                    continue
                unhashable.append(k)
                out.append(r)
            else:
                if h in seen:
                    continue
                seen.add(h)
                out.append(r)
    return out
"}

